document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("[data-filter-root]").forEach(e=>{const t=e.querySelector(".filter-chips");if(!t)return;const s=Array.from(t.querySelectorAll(".filter-chip")),o=Array.from(e.querySelectorAll("[data-tags]")),n=Array.from(e.querySelectorAll("[data-filter-group]"));function i(e){s.forEach(t=>t.setAttribute("aria-pressed",String(t.dataset.filter===e))),o.forEach(t=>{t.hidden=e!=="all"&&!t.dataset.tags.split(" ").includes(e)}),n.forEach(e=>{e.hidden=!e.querySelector("[data-tags]:not([hidden])");const t=!!e.querySelector("[data-tags][hidden]");e.querySelectorAll("[data-filter-whole]").forEach(e=>{e.hidden=t})});const t=n.find(e=>!e.hidden);n.forEach(e=>e.toggleAttribute("data-filter-first",e===t))}t.hidden=!1,t.addEventListener("click",e=>{const t=e.target.closest(".filter-chip");t&&i(t.dataset.filter)})})})